import StoreBase from './StoreBase';
import { Constructor, StoreOptions } from '../types/store';
/**
 * create a store and return `useStore, injectStore, getStore, preloadStore, getState`
 *
 * @param  {Constructor<T>} InjectedStoreClass store class
 *
 * @example
 * ```ts
 * import { createStore} from 'matrox'
 *
 * const { useStore, injectStore, getStore, preloadStore, getState } = createStore(Store)
 * ```
 *
 * @see https://github.com/anthhub/matrox#createStore
 */
declare const createStore: <T extends StoreBase<T, string>>(InjectedStoreClass: Constructor<T>, options?: StoreOptions) => {
    useStore: (identification?: number | string) => Readonly<T>;
    injectStore: (identification?: number | string) => any;
    getStore: (identification?: number | string) => Readonly<T> | undefined;
    preloadStore: (identification?: number | string) => void;
    getState: (identification?: number | string) => import("../types/store").PlainObject;
};
export default createStore;
